(window.webpackJsonp=window.webpackJsonp||[]).push([[95],{529:function(t,s,_){"use strict";_.r(s);var v=_(11),e=Object(v.a)({},(function(){var t=this,s=t.$createElement,_=t._self._c||s;return _("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[_("p",[_("font",{attrs:{size:"5"}},[t._v("摘要：")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("1、在试探中，魔鬼他首先把你的需求展示给你，然后把脱离了神来满足这个需求的手段告诉你，并且让你看到用这个手段确实有可能实现需求。需求是你当时客观具有的；手段和实现需求之间的可能性也是客观在那儿的；你能决定的，就是是否去动用这个满足需求的手段。拒绝这种手段，你就胜过试探了。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("2、要做到这一点，首先就是你得知道哪些手段是违背了神的。这就需要你对神的旨意非常熟悉，所以要昼思夜想神的律法。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("3、除了要知道神的律法外，试探来临时，真要能抵御试探，还需要你敢于把自己的需求放弃了：我豁出去了，我的需求不满足就不满足了。这意味着在你的价值体系当中，神比你重要。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("4、在面对试探时，你要敢于放弃自己的需求，这需要你积累足够的信靠经验。信靠经验是从日常小事上积累的。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("5、有足够信靠经验的人，当他的需求没有被满足时，他除了祷告求神来满足，并且他同时还会关注另一个问题：那我按照神的话应该如何来回应这种处境？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们平安。上一次我们进入到路加福音的第4章。我们今天继续停留在4:1~13节这一段经文中，我们从另一个角度来分享这段经文。我们一起来看一看，耶稣是如何胜过这些试探的。而他和我们都是人，他可以做到，意味着我们也可以做到，我们也可以效法。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("一、拒绝脱离神的手段")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("上次我们已经说了，试探有三个要素：被试探的人需要某个东西，并且他也能做某个行为以获得这个东西，并且他做了之后，是可能确实会成功地获得这个东西的。然后魔鬼呢，就在第二个要素上面动手，他提供给你一种脱离神来满足需要的手段，这样就挑动起了你的私欲——也就是用脱离神的方法来满足自己需求的欲望。有了这个私欲，就有了犯罪的可能性。因为私欲怀了胎，就生出罪来。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("所以，你有需要不等于就是有私欲。私欲是一种脱离了神来满足自己需求的欲望。而魔鬼所做的，就是用试探去挑动人的私欲。他首先把你的需求展示给你，然后把脱离了神来满足这个需求的手段告诉你，并且让你看到用这个手段确实有可能实现需求，这样来引动你的私欲。当试探到来时，需求是你当时真实具有的，你改变不了；手段和实现需求之间的可能性也是客观在那儿的，你决定不了；你能决定的，就是是否去动用这个满足需求的手段。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("拒绝这种手段，你就胜过试探了。这正是耶稣做的事情。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("在第一个试探中，耶稣确实身体饥饿，这是他当时真实的需求。但魔鬼告诉他，你可以用诉诸神性的方式来满足这个需求。如果耶稣诉诸神性，就意味着道成肉身失去了意义，就意味着他破坏了天父的计划、违反了天父的旨意，所以这是一个脱离了神来满足需求的手段。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("而耶稣的回答正显示了他的拒绝。他在第4节回答 ：“经上记着说：‘人活着不是单靠食物，乃是靠神口里所出的一切话。’”耶稣承认人活着需要食物，这是真实的需求，但“不是单靠食物”，乃是“靠神口里所出的一切话”。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这句话来自申命记第8章。在那里摩西回顾了神在旷野引领以色列人，然后在申命记8：3节说神这40年中苦练他们，任他们饥饿，只赐下他们不认识的吗哪给他们吃，是要让他们知道“人活着，不是单靠食物，乃是靠耶和华口里所出的一切话。”")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("申命记这段经文告诉我们，神对以色列人训练40年，就是要让他们形成一种思维模式：他们维持物质肉身所需的充分且必要的条件是耶和华的命令。食物只不过是耶和华用于成就他命令的手段而已。耶和华说你活着，你就活着，他可以通过使用食物让你活着，也可能不使用食物，让你照样活着。他可以通过给你吃鸡鸭鱼肉、五谷杂粮、瓜果蔬菜让你活着，也可以通过只让你吃吗哪让你活着。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("耶稣引用这句话，就说明他有这个思维模式，所以他就不会去舍本逐末，采用违反天父旨意方式去满足自己的需要，这样魔鬼这个试探就不会在他那儿形成私欲。那私欲连胎都没有怀，当然就更不会生出罪来了。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("在第二个试探中，耶稣确实想要获得对万国的权柄以及荣耀，这是他来到这里的目的，是他的真实的需求。这个我们上次已经讲过了。魔鬼给他提供的手段是你向我下拜。而耶稣的回答是：“当拜主你的神，单要事奉他。”这句话出自申命记6章，那里摩西告诫以色列人进入迦南地之后，只可敬畏耶和华，不可去随从别神，因为耶和华是忌邪的神。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("耶稣在这里也同样是否定了魔鬼提出的这种满足需求的手段，而是坚定地选择不偏离神，单单敬拜神，所以他不会产生私欲，自然也就不会犯罪。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("第三个试探中也一样。耶稣需要确认神对他的爱——（我顺便说一下，上一次有姐妹在分享的时候提到，自己在患难、试探当中时，常常觉得神是在惩罚她，而没有在爱她。我想这更能说明耶稣当时的状态。当时耶稣自己知道自己落入到试探当中，也自己知道是顺服天父的旨意而落入到试探当中，因此在此时此刻，他更需要确认天父是爱他的，和你们一样），而魔鬼给他提供的手段是跳下圣殿，让神派天使来接住你，这样你就知道神是爱你的了。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("耶稣的回答什么呢？“经上说：‘不可试探主你的神。”这段经文出现在申命记6:16节，那里摩西警告以色列人不可试探耶和华，像在玛撒那样试探他。以色列人在玛撒试探神的历史记载在出埃及记第17章，当时百姓没有水喝了，就与摩西争闹，说“耶和华是在我们中间不是”（出埃及记17:7）。也就是说，他们要让耶和华给他们提供水，以此证明耶和华在他们中间，或者我们也可以说证明耶和华爱他们。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这种行为的本质是什么呢？就是要凌驾于神，让神来为他们服务。在这样的一种关系中，他们要神按照他们选择的方式来爱他们，而不是接受神自己所决定的方式。这当然是一种脱离了神、违背神的方式。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("耶稣这里面临的试探也是这样。耶稣需要神的爱，也需要不断确认神爱他、保护他，但是他不接受用凌驾于神、让神来为我服务这样的方式来满足这个需要。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("所以我们从这些经文可以看到，耶稣抵御试探的方法，就是拒绝魔鬼所提供那种违背了神、脱离了神来满足自己需要的手段。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我们知道了方法，说起来很简单。但紧接着的问题是，我们怎么才能做得到？当试探来临的时候，我们怎么才能真正去拒绝那种违背神的手段？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("二、昼思夜想神的律法")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("那么很自然，首先就是你得知道哪些手段是违背了神的。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这意味着你需要知道神的旨意是什么。耶稣之所以会坚持抑制自己的神性，不动用自己的神性来把石头变成食物，是因为他首先知道天父的旨意是要让他虚己，成为人的样式；他之所以不去拜魔鬼，是因为他首先知道神的旨意是要人单单侍奉他，不能拜其他任何东西；他之所以不会从殿顶跳下去，是因为他首先知道神不允许人把自己凌驾于他之上。耶稣很清楚神的这些旨意。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("对我们每个人来讲也是这样，首先你得知道神的旨意是什么。而神对我们的旨意，就体现在他的律法当中。他对我们每个人在每个情境下的具体旨意，也绝不可能与他的律法相违背，所以我们需要熟悉、掌握神的律法。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我们的主耶稣给我们做了很好的榜样，他自己就是非常清楚知道神的律法。所以我们看到，耶稣在回答魔鬼的试探的时候，每一次都是用神记载在律法中的话来回答。在面对第二个试探的时候，耶稣引用了申命记第6章13~14节。那里明确指示不可以随从别神。在面对第三个试探的时候，耶稣引用申命记第6章16节，不可试探耶和华你们的神。神的旨意很清楚。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("在第一个试探，耶稣引用的是申命记第8章3节。虽然这一节并没有明确指出神要求圣子抑制自己的神性、作为人活在世上、在人性中受试探，而是说“人活着，不仅靠食物，而是靠神口里的一切话”。但这句话表明的是对于我们作为人如何存活在世上，神的旨意是什么：就是要完全依赖在他口中的话，不能去依赖于人自己的聪明、才智、计划。这就是对于我们如何活下去，神的旨意。所以耶稣作为人要活下去，同样也是如此，虽然他饿了，但他必须依赖于神的命令，不是靠自己的计划和想法，神没有让做的事情，他就不能去做，神没让他去把石头变成面包，他就不能去变，即使这是为了活下去。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("那你呢？你对神的律法掌握得怎么样？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我举个几个例子。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("某个基督徒姐妹遇到一个自己特别喜欢的男生，但是这个男生不信主。那么这个姐妹和这个男生结婚，是符合神的律法，还是违背神的律法？大家知道吗？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("学校的老师找你，让你签署一个否定信仰的声明。那么签署这个声明，是符合神的律法，还是违背神的律法？大家清楚吗？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("明天你去学校上课、为老师做课题，因为你想要毕业，因为你想要做出一番成就来，又或者因为你想要找到一份好工作，有能力娶妻生子，建立一个温暖的家庭。那么你这样去上课、做课题，是符合神的律法，还是违背神的律法？大家想过吗？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我去给人讲道，别人来感谢我，说你的讲道太有逻辑了，太深刻了，太造就人了，然后我就想我真是很有能力啊，我真是聪明啊。那我这样去服侍，是符合神的律法，还是违背神的律法？大家清楚吗？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("曾经我知道的一个教会的带领人，他为了服侍教会的弟兄姐妹付出了很多的努力，教会也搞得红红火火，很多弟兄姐妹都得到了造就。但是他和他的妻子就是搞不好关系，管理不好自己的家。那么他来带领教会，这是符合神的律法，还是违背神的律法？大家知道吗？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我还知道一个曾经的牧师，他从美国远渡重洋来中国，建立教会、服侍弟兄姐妹，教会最多的时候曾经人数达到数百人。但他来之前，他的妻子不愿意放下在美国的工作。所以他这么多年都是一个人在中国为主做工。那么他来中国宣教、建立教会，这是符合神的律法，还是违背神的律法？大家清楚吗？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("无论是涉及你们个人生活的，还是教会运作的，方方面面的事情，我还可以列举很多很多。在每个情境中，你是否都清楚，你做或不做某个行为，你带着怎样的动机、心态来做某个行为，是符合神的律法，还是违背神的律法？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("要达到这一点，需要怎么样？诗篇第1篇就告诉我们：要昼思夜想神的律法。你去学习、去默想、去把你的每个行为和神的律法相对照，把神的律法挂在心上，这就叫昼思夜想。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("如果你都不知道神的律法是什么；不知道原来神是禁止基督徒和非基督徒结婚（林前7:39；林后6:14）；不知道神警告我们“在人面前否认我的，我在父面前也否认他”（太10:33）；不知道神要求我们只能为荣耀他而做事（林前10:31）；不知道神说我要抵挡骄傲的人（彼前5:5）；不知道神说“人不能管好自己的家，就不能管理神的教会”（提前3:5）；不知道神说“夫妻不可彼此亏负，除非两相情愿，暂时分房，为要专心祷告方可。”（林前7:5）")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("你都不知道！那你面对试探的时候，自然就是混乱的。甚至更可悲的是，有些情况下你自己认为做的是讨神喜悦的，但实际上在神看来却是令他厌恶的。正像何西阿书4:6节中，神所感叹的：“我的民因无知而灭亡”。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("所以弟兄姐妹们，我们要勤于学习神的律法，要会用神的律法来判断每一个事情，无论是我们自己的，还是教会的，还是其他人的。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我可以这样说：你每天所面对的每一个事情，对你而言都可以说是一个试探。因此在面对每一个事情的时候，你都要考虑神的律法是怎么说的，我做这个或者不做这个、带着怎样的动机和心态来做某个行为，是违背他的律法还是符合他的律法。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("三、敢于放弃你的需要")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我们已经说过了，胜过试探，就是拒绝用违背神的手段来满足自己的需要。所以首先你得知道，什么手段是违背神的，什么手段是不违背神的。因此学习、熟悉律法是第一步。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("但光认识、熟悉了还不够。当试探实际临到时，我们还需要把这种认识确实地去付诸实践。这才是真正拒绝了这种脱离神的手段，抵御住了试探。那如何才能真正付诸实践？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我们来看主耶稣在试探当中是如何做的。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("在第一个试探当中，他禁食四十天后，神又撤走了对他身体的能量供应，因此他处于极度的饥饿状态。这时候耶稣的需要是吃东西，否则他可能会饿死，或者我们可以说他需要活下去。这是一个客观、真实的需要。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("所以魔鬼这个时候让他去靠自己的聪明才智、计划，去诉诸自己的神性，来满足这个吃东西的需要，解决这个活下去的问题。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("耶稣当然知道神的旨意是什么，所以这个时候他面临着两个选择：要么他违背神的旨意，接受魔鬼的办法，把石头变为食物，让自己可以活下去；要么他顺服神的旨意，拒绝魔鬼的方法，就这么继续饿着。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("大家要注意，耶稣此刻一直抑制着自己的神性，因此他作为人，不是全知的，他不知道自己还要饿到什么时候。所以如果他做后面一个选择，就意味着他要承担一个风险：既然“人活着不是单靠食物，乃是靠神口中的一切话”，那么如果神的话是不让他活，意味着他就不能活，就得死。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("大家看到了吗？他选择听从神的话，就面对着一个可能性，就是他可能会饿死，他的需求可能不会得到满足。而耶稣选择听从神的话，实际上就意味着他做了一个决定：我即使死也不违背神的话；如果神要我死，那死就死吧。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("在第二个试探中也是同样的。耶稣想要对世界的权柄，所以魔鬼说，你来拜我，我就把权柄给你。耶稣这时候也面临着两个选择：要么他违背神的律法，接受魔鬼的方法，获得权柄；要么顺服神的律法，拒绝魔鬼的方法。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("但选择后者意味着什么呢？当然首先就是，他此时此刻不能从给魔鬼那儿获得对受造界的权柄；另外呢，他将面临着未来一个不确定性，也就是他到底能否完成神交付给他的使命、能否“顺服到底，以至于死，且死在十字架上”，然后被神升为至高，获得那超乎万名之上的名？这都是不确定的。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我再次说，我们不要站在福音书的最后来看耶稣现在的状态；也不要以耶稣的神性来理解他在人性中的状态。他现在还没有开始自己的事工。神会怎么带领他的事工？他会遭遇多大的艰难？后面还有多少的试探？他自己到底能不能承受得住？作为当时的耶稣这样一个人来讲，都是不确定的。路加福音4:13章也说，当他胜过了这些试探，魔鬼只是暂时离开了他。说明以后还会再来。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("所以在耶稣看来，他是有失败的可能性的。拒绝了跪拜魔鬼，就意味着他接受了这样的可能性，或者说他做了这样的决定：我即使未来最终会失败，但此时此刻，我不违背神的话；如果我有一天失败了，没有完成神的任务，没有获得对受造界的权柄和荣耀，那失去了就失去了吧。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("第三个试探不是特别明显，但如果我们仔细去考虑耶稣当时的心态，其实也是这样。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我们再来体会一下耶稣当时的状态。是神将耶稣引入到旷野去遭受试探；而耶稣是一个人在旷野（马可福音1:13节记载，当时那里除了他就只有野兽）。所以我们看到，在这些试探中，他实际上是处于一种孤立无援的状态。他此时的状态，可能与旧约当中的约伯很类似。神当然还是与他同在。神注视着，但也沉默着，让他们独自去面对外在的艰难环境。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这种状态还有持续多久？不知道。我们只知道持续得越久，对人的心理压力就越大，就越需要一些好消息、一些正面的安慰，让自己能够支撑下去，而这个时候就越想要靠自己去寻找这样的安慰。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我们来看一个例子。大家翻到出埃及记第24章最后。这里的背景是神与以色列人立约，然后神让摩西再次上到山上，神好把石板并他所写的律法和诫命赐给他，让摩西以后可以教训百姓（出24:12）。然后18节记载，摩西在山上待了40个昼夜。接下来我们一起看出埃及记第32章，我们来看出埃及记32:1：人民见摩西迟迟不下山，就聚集到亚伦那里去，对他说：“起来，为我们做神像可以走在我们前头领路，因为那摩西，就是把我们从埃及地领出来的那个人，我们不知道他遭遇了甚么事。”")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("那个时候摩西已经离开以色列人上山有40天了。他们不知道摩西到底出了什么事情，甚至不知道他是不是还活着。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我们想象一下，当时他们在旷野中，刚从埃及地出来三个月，不知道自己该往哪里去。那个曾经引领他们的人，又生死未卜，下落不明。所以以色列人当时其实也和耶稣一样，是独自在旷野当中。他们看不清楚前面的方向，他们不确定自己未来会怎么样。在这种迷茫中，他们需要一些确定性，需要一些好消息，需要一些安慰。他们等了一天，这个需要没有得到满足；等了两天，没有得到满足；等了三天，没有得到满足；等了10天，没有得到满足；等了20天，没有得到满足；等了第30天，还没有得到满足；等到第39天，这个需求还没有得到满足。最关键的是，他们不知道还要等到什么时候。摆在他们眼前的，是无边无际的等待。所以到第40天，终于崩溃了。干脆自己想办法来得到安慰，让亚伦给他们造一个金牛犊，他们就落入了拜偶像的罪当中。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("大家体会到这种心理压力了吗？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这种压力以色列人有，他们承受不住了，所以用自己的方法去寻求安慰，为自己造了金牛犊；")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这种压力约伯也有，因此他想要见到神，问问他到底是怎么回事（约伯记23章1~8），这对他而言，也是一种安慰。可惜的是，他找不到神，神沉默了（约伯记23:8~9）")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这种压力当然耶稣也有。魔鬼因此告诉他：“你用自己的方法来求安慰吧，用自己的方法确认神爱你。你从殿顶跳下去，他会让天使托住你，你就知道神还与你同在，他还在爱着你。”")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("所以这个时候耶稣也面临着两个选择：要么他接受魔鬼的方法，从这里跳下去，被神保护，获得安慰；要么他拒绝魔鬼的方法，继续独自在这旷野中面对艰难，不知道还要多久，也许还要一天，也许还要三年，也许还要十年，也许还要四十年，如果他能活到那个时候的话。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("而他拒绝了用自己的方法来寻求安慰，就意味着他接受了这样的可能性，或者说他做了这样的决定：我即使一直这样，我也不违背神的话；如果神就是要一直沉默，让我独自面对这些艰难，那就这样吧。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("所以我们看到，在第一个试探中，耶稣接受了的物质身体产生的需求得不到满足的可能性；在第二个试探中，耶稣接受了他的生命目的产生的需要得不到满足的可能性；在第三个试探中，耶稣接受了他的位格关系产生的需要得不到满足的可能性。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我们在上一次谈到试探的特征的时候，讲到所有试探都有三个要素：被试探的人有某个需求，他也能做某个行为，并且他做了之后，有可能确实会成功地满足这个需要。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("大家发现没有，这里面也出现这样一个概念：可能性。魔鬼试探你的时候，会让你看到一种“可能性”，就是通过违背神的方式满足自己需求的可能性；而你要拒绝试探，你要面对另一种可能性，就是自己的需求得不到满足的可能性。当你面对这后一种的时候，你必须在心里做出一个决定：我豁出去了，不满足就不满足了。当你做出这个决定，也就意味着你把这些需求放弃掉了，你不再去在乎它了。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("而且这种选择不是在权衡了两种可能性的大小之后而做出的。第一个试探中，耶稣自己让石头变成食物，因而他可以吃饱、活下去的成功可能性，比他饿死的可能性可是大得多的。如果要是权衡所谓的利弊，权衡两种可能性的大小，那么他就该选择听从魔鬼的话。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("但对于耶稣来讲，这和两种可能性的大小无关，而是和它们所牵涉的那个方法有关。试探中的这个“需求会被满足的可能性”，牵涉的是违背神的方法；而拒绝试探中的这个“需求不会被满足的可能性”，牵涉的是顺服神的方法。哪怕遵守神的话，100%将导致我的需要的不到满足，而违背神的话，100%会导致我的需要将得到满足，我也应该选择顺服神的话。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("换句话说，在你的价值体系中，遵守神的话是超越于自我需要的满足的。或者我们再说简单一点：在你的价值体系中，神是比我重要的。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("因此，在你面对神的话的时候，你要放弃自己的需求来顺服于神的话。而什么时候你在面对神的话呢？无时无刻不在。你怎么吃饭，怎么喝水，神都要介入，神都是对你有旨意的。所以我们应该无时无刻不在放弃自己的需求。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这就叫“先求神的国和神的义”，这就叫“舍己”，这叫“撇下一切”。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我不知道大家在信主的时候，想过这个问题没有？耶稣劝我们要想。在路加福音14章25节~33节，耶稣说你们来跟随他，是要计算代价的。在最后他说：“你们无论什么人，若不撇下一切所有的，就不能做我的门徒”。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("在你信主之后，老师威胁你不给毕业了，论文写不出了，实验做不出来了，没有男朋友或者女朋友孤独寂寞了，升不了职了，不被尊重了，身体被查出疾病…….在面对这些自己的需求没有被满足的时候，你也同样需要一次又一次再次地做出决定：我是否要撇下自己的需要，来跟随他？也就是无论我的需求会不会满足，我都按照神的旨意行，满足不了就算了。当这些事情临到你的时候，你敢不敢这样？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这就是我们讲的第二点。要胜过试探，除了要知道神的旨意是什么，你还要敢于把自己的需要放弃掉。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("把自己想象成一条没有系绳子的小舟，神的旨意是汪洋大海，你把自己放在这个海上，任它把你飘向哪儿就飘向哪儿。你敢不敢？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("四、努力积累信靠经验")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("基督徒，都会说自己愿意撇下一切所有的来跟随他；但我想大部分基督徒，尤其是年幼的基督徒，真正试探临到时，是不敢的，或者是没有那么敢的。我说的年幼，是指属灵上的。这不在于你的生理年龄，也不在于你信主了多少年了。有些人信主了十几二十年，可能仍然还是停留在属灵上的小婴孩阶段。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("如果是这样，那么即使你很熟悉神的律法，但也当然就没有办法胜过试探。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("好，那下一个问题就是，我怎么才能敢？别忘了，耶稣也是人，他能做到的，你也能做到；他既然敢，那你也应该能敢。那耶稣是怎么能做到的？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("你要想这个代价的问题，然后做出决定。在你信主的时候，就要做决定，你是否愿意撇下一切所有的，来跟随他？什么叫跟随他？他怎么做你就怎么做，这叫跟随。而他只做一件事，就是按照神的旨意行。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这需要我们再次回到路加福音第2章40~52节。我们曾经在"),_("RouterLink",{attrs:{to:"/_posts/路加福音释经讲道（05）做正常人.html"}},[t._v("《做正常人》")]),t._v("这篇证道中对这段经文进行了讲解；在"),_("RouterLink",{attrs:{to:"/_posts/路加福音释经讲道（06）活在真实的历史中.html"}},[t._v("《活在真实的历史中》")]),t._v("，我也提到过这段经文。这是非常重要的一段经文。")],1)],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这里是整本圣经唯一记载耶稣童年情况的地方。第40节说到他渐渐长大，然后记载了耶稣12岁上耶路撒冷的一段经历。他从拿撒勒这个小地方到耶路撒冷，结果独自留在圣殿中学习神的话。当他的父母找到他，问他为何这样让他们担心的时候，在第49节，耶稣说“为什么找我呢？岂不知我应当以我父的事为念吗？”这最后一句话，也可以翻译为“我应当在我父的家里吗”。然后我们看第51节，他就同他们下去，回到拿撒勒，并且顺从他们。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我们一定要正确理解这段经文。耶稣滞留在耶路撒冷学习圣经，是在以天父的事为念，是在天父的家里；而他离开耶路撒冷，回到拿撒勒，顺从马丽亚和约瑟，不是说他就不以天父的事为念，就离开天父了。不！他也在以天父的事为念，也是在天父的家里，只是换了不同的方式，换了不同的时空。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("也就是说，耶稣在童年的时候，无论做什么，一直在以天父的事为念，一直在天父的家里，或者说，他的心思意念一直想的都是神的事情，他的思维一直在天父那里，他一直在与天父保持着相交。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这种状态的结果是什么呢？2章52节说“他的智慧和身量，并神和人喜爱他的心，都一齐增长。”不仅他的肉体（就是身量）在增长，也不仅是他和周围人的和谐、亲密关系在增长，他的智慧、他与神的和谐、亲密的关系也在不断增长。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("既然是以神的事为念，说明在生活中每一个细节中，每一件事上，他都需要思考神的旨意是什么；他都需要做出决定，放弃自己的需求，遵从神的旨意。到我们今天的经文为止，他已经这样生活了三十多年。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("在这样的生活方式下，他会积累下什么？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("是经验。是与神相交的经验！这三十多年，在每一分每一秒，大大小小的事上，他都在经验：我放弃自己的需求、遵从神的旨意，到底会发生什么。而每经验一次，他发现神都在带领他、保护他，要么会满足他的需要，要么会给比他当时自认为的需要更好的。这样一来，他的头脑中就会越来越深地刻入这样的认知：神是良善的；遵守他的旨意，对我而言是好的，他不会害我；相比我自己，他才知道什么是真正对我好的。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("这就是信靠经验。这种经验越多，他对神的信靠就越多。信靠越多，他又会经验越多。所以到了路加福音第4章，他进入到这样的试探中，他才敢做出决定：我死就死吧，我未来得不到对万物的权柄就得不到吧，我需要继续孤独地在旷野里就让我继续在这里吧。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，我们也是同样的。当试探临到你时，你敢放弃自己的需要，其实就是需要你信靠神。你需要相信神对你是良善的，他不会害你；比起你自己，他才知道什么是真正对你好的，因此遵守他的旨意，比满足你的需要更重要。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("而你要在那个时候你敢、你能够信靠他，其实就是需要你在平时不断去积累这种信靠经验。从小事上做，从生活的点点滴滴上去做，在任何一个生活场景下，都去思考神的旨意是什么、去放弃自己的需求、去遵守神的旨意，并且去经验神对你的良善。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("基督徒为什么吃饭之前要祷告？这不是仪式。而是使用我们的每一餐，来不断确认，是神赐给我的饮食，他良善地供应着我。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("保罗为什么教导信徒要常常喜乐，不住祷告，凡事谢恩（帖前5:16~18）？就是让我们在各种小事当中去获得这样的信靠经验，让我们有意识地去看到神的良善。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("所以我们自己，也要有意识地从日常生活中去操练以神的旨意为大，放弃自己的需求，去体认神的恩典。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我就以吃饭喝水为例。我的需求是什么呢？是饿了，是渴了，是想吃大餐了，想喝奶茶了。而神的旨意是什么呢？你们或吃或喝，都要为荣耀神而行（林前10:31）。所以你在这件事情上也要去遵守神的旨意，就是为了荣耀神而去吃或者喝，而不是为了满足你自己的口舌之欲。如果是这样，那么你该吃什么、喝什么，该怎么吃、怎么喝，可能都应该要发生变化才对。当可以选择的时候，吃什么是对你身体健康的，因此你可以有更健康的体魄来服务神？这是不是就应该纳入你的考虑当中？当没有选择的时候，天天只能吃糠咽菜，你是不是也应该要感谢神的恩典？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我再以一些还在读研究生的弟兄姐妹的学习生涯为例。你的需求是什么呢？是为了毕业，有好工作，生活幸福。而神的旨意是什么呢？是要你忠心事奉你的老板，好像事奉主（弗6:7）。所以在你做项目的事情上，要放弃自己的需求，不是为了你自己要毕业、找工作、生活幸福而学习研究，而是很单纯，神现在把我放在这儿，我的导师让我干这个，我就忠心地去干就行了。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("我再次提醒大家，耶稣说“人在最小的事上忠心，在大事上也忠心；在最小的事上不义，在大事上也不义。”（路16:10）你想要在大的试探上敢去放弃自己的需求，就先在每天的小事上去放弃自己的需求，主动去积累信靠经验。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("其实当我们像耶稣一样，随时以天父的事为念，随时是住在天父那里，不断舍弃自己的需要，不断积累信靠经验，我们看待问题的角度就会发生变化。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("从我们外面的人来看，在路加福音4章记载的这三个试探中，耶稣有来自物质肉身的需求，有来自生命目的的需求，有来自位格关系的需求。这些需求是客观存在的、真实的，所以很自然，我们会考虑怎么去满足它们。魔鬼也是这样考虑的，因此他提供给耶稣脱离神的手段。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("但其实耶稣积累了足够的信仰经验，他习惯了生活在神的旨意当中，因此他虽然客观上有这些需要，但他主观上，除了向神呼求来满足这些需要之外，他还会考虑另外一个问题：当我饿了的时候，我按照神的话应该如何来回应这种处境？当魔鬼指给我看的万国的荣华，我按照神的话应该如何来回应这种处境？当我一个人孤独地在旷野中，我按照神的话应该如何来回应这种处境？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("大家看到了吗？要胜过试探，问对问题很重要。一般人的问题是，我有需要没有被满足，我要怎么去满足？而一个有充足的信靠经验的人，他当然知道只能祷告祈求神来满足，并且他同时还会关注另一个问题，我有需要没有被满足，这是一个处境，好，那我按照神的话应该如何来回应这种处境？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("当老师威胁我不签字否认信仰就影响我毕业了，我按照神的话应该如何来回应这种处境？当我遇到一个自己特别喜欢的不信主的异性，我按照神的话应该如何来回应这种处境？当我做不出实验，老师不让我毕业的时候，我按照神的话应该如何来回应这种处境？当我找不到男朋友或者女朋友，我按照神的话应该如何来回应这种处境？当我的妻子得了癌症可能就快要死了，我要怎么按照神的道去回应这个处境？当我的儿子悖逆，不愿意去上学，我要怎么按照神的道去回应这个处境？")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("当我们能去思想这些问题的时候，魔鬼就不可能提供一种脱离神的手段，让我们来满足我们的需要，那在面对他的试探时，我们自然就可以拒绝了。")])],1),t._v(" "),_("p",[_("font",{attrs:{size:"5"}},[t._v("但形成这样的看问题的习惯，需要我们知道神的旨意是什么，需要我们一直浸泡在与神的相交当中，从小事做起，在点点滴滴中去体认他的良善，这样你在面对试探的时候，才敢告诉自己：对于神给我指的路，我就是要一条道走到黑，我的需要满足不了，我认了。")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);